[package]
name = "cypcb-autoroute"
version.workspace = true
edition.workspace = true
license.workspace = true
description = "A*-based PCB autorouter for CodeYourPCB"

[dependencies]
cypcb-core = { workspace = true }
cypcb-world = { path = "../cypcb-world", default-features = false }
cypcb-rules = { path = "../cypcb-rules" }
cypcb-router = { path = "../cypcb-router" }
bevy_ecs = { workspace = true }
pathfinding = "4"
tracing = { workspace = true }

[dev-dependencies]
cypcb-parser = { workspace = true }
cypcb-rules = { path = "../cypcb-rules" }
cypcb-world = { path = "../cypcb-world" }

//! A*-based PCB autorouter for CodeYourPCB.
//!
//! Replaces the FreeRouting JAR dependency with a custom routing engine
//! that produces `RoutingResult` output compatible with the existing
//! `apply_routes()` pipeline.
//!
//! # Workflow
//!
//! 1. Build a [`RoutingGrid`] from a `BoardWorld` and design rules
//! 2. Call [`route_board()`] to run the A* router on all unrouted nets
//! 3. The returned [`RoutingResult`] contains segments and vias ready for `apply_routes()`
//!
//! # Example
//!
//! ```rust,ignore
//! use cypcb_autoroute::{route_board, AutorouteConfig};
//! use cypcb_rules::presets::{RulesPreset, PresetRuleSet};
//!
//! let config = AutorouteConfig::default();
//! let preset = RulesPreset::from_name("jlcpcb").unwrap();
//! let rules = PresetRuleSet::new(preset);
//! let result = route_board(&world, &library, &rules, &config);
//! ```

pub mod cost;
pub mod grid;
pub mod pathfinder;

use cypcb_router::types::RoutingResult;
use cypcb_rules::RoutingRuleSet;
use cypcb_world::footprint::FootprintLibrary;
use cypcb_world::BoardWorld;

/// Configuration for the autorouter.
#[derive(Debug, Clone)]
pub struct AutorouteConfig {
    /// Grid resolution in nanometers. Smaller = more precise but slower.
    /// Default: derived from `min_clearance / 2` (~63µm for JLCPCB).
    /// Set to `None` to auto-derive from rules.
    pub grid_resolution_nm: Option<i64>,

    /// Maximum rip-up-and-retry iterations before giving up on a net.
    pub max_ripup_iterations: u32,

    /// Cost multiplier for placing vias. Higher = fewer vias.
    pub via_cost_multiplier: f64,

    /// Whether to prefer routing on the top layer when possible.
    pub prefer_top_layer: bool,
}

impl Default for AutorouteConfig {
    fn default() -> Self {
        Self {
            grid_resolution_nm: None,
            max_ripup_iterations: 10,
            via_cost_multiplier: 1.0,
            prefer_top_layer: true,
        }
    }
}

impl AutorouteConfig {
    /// Resolve the grid resolution: use explicit value or derive from rules.
    pub fn resolve_grid_resolution(&self, rules: &dyn RoutingRuleSet) -> i64 {
        self.grid_resolution_nm.unwrap_or_else(|| {
            let clearance = rules.constraints_for_net(0).min_clearance;
            // Half the minimum clearance gives good resolution
            (clearance.raw() / 2).max(10_000) // floor at 10µm
        })
    }
}

/// Route all unrouted nets on the board.
///
/// This is the main entry point for the autorouter. It builds a routing grid
/// from the board world and design rules, then attempts to route each net
/// using A* pathfinding with rip-up-and-retry.
///
/// # Arguments
///
/// * `world` - The board world containing components, pads, zones, and existing traces
/// * `library` - Footprint library for pad geometry lookup
/// * `rules` - Design rules providing clearances, widths, and via costs
/// * `config` - Autorouter configuration (grid resolution, iteration limits, etc.)
///
/// # Returns
///
/// A `RoutingResult` containing all generated route segments and vias, or a
/// failure status if routing could not complete.
pub fn route_board(
    _world: &mut BoardWorld,
    _library: &FootprintLibrary,
    _rules: &dyn RoutingRuleSet,
    _config: &AutorouteConfig,
) -> RoutingResult {
    RoutingResult::failed("autorouter not yet implemented")
}

//! Routing grid for discretizing the PCB board into cells.
//!
//! The [`RoutingGrid`] converts the continuous board space into a uniform grid
//! where each cell tracks per-layer occupancy. This enables A* pathfinding
//! on a discrete graph structure.
//!
//! # Coordinate System
//!
//! The grid uses the same coordinate origin as the board (top-left corner).
//! Board positions in nanometers are converted to grid indices via integer
//! division by the grid resolution.

use cypcb_core::{Nm, Point};
use cypcb_rules::RoutingRuleSet;
use cypcb_world::footprint::FootprintLibrary;
use cypcb_world::{BoardWorld, Layer};

/// Cell occupancy flags (bitfield).
pub const CELL_FREE: u8 = 0;
pub const CELL_PAD: u8 = 1 << 0;
pub const CELL_TRACE: u8 = 1 << 1;
pub const CELL_ZONE: u8 = 1 << 2;
pub const CELL_VIA: u8 = 1 << 3;
/// Generic obstacle (clearance bloat, board edge, etc.)
pub const CELL_OBSTACLE: u8 = 1 << 4;

/// Statistics about the routing grid.
#[derive(Debug, Clone, Default)]
pub struct GridStats {
    /// Grid width in cells.
    pub width: u32,
    /// Grid height in cells.
    pub height: u32,
    /// Number of routing layers.
    pub layers: u8,
    /// Total occupied cells across all layers.
    pub obstacle_cell_count: u64,
    /// Grid resolution in nanometers.
    pub resolution_nm: i64,
}

/// A discretized routing grid for the PCB board.
///
/// Each cell is a `u8` bitfield tracking what occupies that position
/// on each copper layer. The grid is indexed as `[layer][y * width + x]`.
///
/// # Grid Resolution
///
/// The default resolution is `min_clearance / 2` from the design rules,
/// typically ~63µm for JLCPCB. This ensures that clearance violations
/// are detectable at the grid level.
///
/// # Coordinate Conversion
///
/// Board coordinates (nanometers) are converted to grid indices:
/// - `grid_x = (nm_x - origin_x) / resolution`
/// - `grid_y = (nm_y - origin_y) / resolution`
///
/// The origin offset ensures the grid starts at (0,0) regardless of
/// the board's position in design space.
#[derive(Debug, Clone)]
pub struct RoutingGrid {
    /// Grid width in cells.
    width: u32,
    /// Grid height in cells.
    height: u32,
    /// Grid resolution (cell size) in nanometers.
    resolution: i64,
    /// Board origin offset in nanometers (top-left corner).
    origin_x: i64,
    /// Board origin offset in nanometers (top-left corner).
    origin_y: i64,
    /// Number of copper layers.
    layer_count: u8,
    /// Per-layer occupancy grids: `layers[layer_idx][y * width + x]`.
    layers: Vec<Vec<u8>>,
    /// Per-cell net ownership for dynamic route tracking.
    /// `net_map[layer_idx][y * width + x]` = net_id or u32::MAX if unowned.
    net_map: Vec<Vec<u32>>,
}

impl RoutingGrid {
    /// Build a routing grid from a board world and design rules.
    ///
    /// Iterates all pads, zones, and locked traces in the board, marking
    /// grid cells as occupied with appropriate clearance bloat.
    ///
    /// # Arguments
    ///
    /// * `world` - Board world with components, zones, and traces
    /// * `library` - Footprint library for pad geometry
    /// * `rules` - Design rules for clearance values
    /// * `resolution_nm` - Grid cell size in nanometers
    ///
    /// # Panics
    ///
    /// Returns `None` if the board has no board entity set.
    pub fn from_board(
        world: &mut BoardWorld,
        library: &FootprintLibrary,
        rules: &dyn RoutingRuleSet,
        resolution_nm: i64,
    ) -> Option<Self> {
        let _span = tracing::info_span!("grid_construction").entered();

        let (board_size, layer_stack) = world.board_info()?;

        let board_width_nm = board_size.width.raw();
        let board_height_nm = board_size.height.raw();
        let layer_count = layer_stack.count.min(32);

        // Only track copper layers for routing
        // For a 2-layer board: layers 0 (top) and 1 (bottom)
        let routing_layers = layer_count.min(32);

        let grid_w = ((board_width_nm + resolution_nm - 1) / resolution_nm) as u32;
        let grid_h = ((board_height_nm + resolution_nm - 1) / resolution_nm) as u32;

        let total_cells = grid_w as u64 * grid_h as u64;
        if total_cells > 10_000_000 {
            tracing::warn!(
                width = grid_w,
                height = grid_h,
                total_cells,
                resolution_nm,
                "Grid exceeds 10M cells — consider increasing resolution"
            );
        }

        tracing::info!(
            board_width_mm = board_width_nm as f64 / 1_000_000.0,
            board_height_mm = board_height_nm as f64 / 1_000_000.0,
            grid_width = grid_w,
            grid_height = grid_h,
            resolution_um = resolution_nm as f64 / 1_000.0,
            layers = routing_layers,
            "Grid constructed"
        );

        let cell_count = (grid_w as usize) * (grid_h as usize);
        let layers_vec: Vec<Vec<u8>> = (0..routing_layers)
            .map(|_| vec![CELL_FREE; cell_count])
            .collect();
        let net_map: Vec<Vec<u32>> = (0..routing_layers)
            .map(|_| vec![u32::MAX; cell_count])
            .collect();

        let mut grid = RoutingGrid {
            width: grid_w,
            height: grid_h,
            resolution: resolution_nm,
            origin_x: 0,
            origin_y: 0,
            layer_count: routing_layers,
            layers: layers_vec,
            net_map,
        };

        // Get min_clearance for bloating
        let min_clearance = rules.constraints_for_net(0).min_clearance;
        let clearance_cells =
            ((min_clearance.raw() + resolution_nm - 1) / resolution_nm) as u32;

        // Mark pads as obstacles
        grid.populate_pads(world, library, clearance_cells);

        // Mark zones as obstacles
        grid.populate_zones(world, clearance_cells);

        // Mark locked traces as obstacles
        grid.populate_locked_traces(world, clearance_cells);

        Some(grid)
    }

    /// Populate pad obstacles from all components in the world.
    fn populate_pads(
        &mut self,
        world: &mut BoardWorld,
        library: &FootprintLibrary,
        clearance_cells: u32,
    ) {
        use cypcb_world::{FootprintRef, Position, Rotation};

        // Collect component data to avoid borrow conflict
        let components: Vec<(Point, f64, String)> = {
            let ecs = world.ecs_mut();
            let mut query = ecs.query::<(&Position, &Rotation, &FootprintRef)>();
            query
                .iter(ecs)
                .map(|(pos, rot, fp)| (pos.0, rot.to_degrees(), fp.as_str().to_string()))
                .collect()
        };

        for (comp_pos, rotation_deg, fp_name) in &components {
            if let Some(footprint) = library.get(fp_name) {
                for pad in &footprint.pads {
                    // Rotate pad position around component origin
                    let pad_pos = rotate_point(pad.position, *rotation_deg);
                    let abs_x = comp_pos.x.raw() + pad_pos.x.raw();
                    let abs_y = comp_pos.y.raw() + pad_pos.y.raw();

                    // Determine pad radius for obstacle marking
                    let pad_radius_nm = pad.size.0.raw().max(pad.size.1.raw()) / 2;
                    let pad_radius_cells =
                        ((pad_radius_nm + self.resolution - 1) / self.resolution) as u32;

                    // Mark on each layer the pad exists on
                    for layer in &pad.layers {
                        if let Some(li) = layer_to_index(*layer) {
                            if (li as u8) < self.layer_count {
                                self.mark_obstacle_at_nm(
                                    abs_x,
                                    abs_y,
                                    li,
                                    pad_radius_cells + clearance_cells,
                                    CELL_PAD,
                                );
                            }
                        }
                    }
                }
            }
        }
    }

    /// Populate zone obstacles from all zones in the world.
    fn populate_zones(&mut self, world: &mut BoardWorld, clearance_cells: u32) {
        let zones = world.zones();
        for (_entity, zone) in &zones {
            if !zone.is_keepout() {
                // Copper pour zones are not obstacles for routing
                // (they fill around traces, not block them)
                continue;
            }

            // Mark all cells within the zone bounds + clearance
            let min_gx = self.nm_to_grid_x(zone.bounds.min.x.raw());
            let min_gy = self.nm_to_grid_y(zone.bounds.min.y.raw());
            let max_gx = self.nm_to_grid_x(zone.bounds.max.x.raw());
            let max_gy = self.nm_to_grid_y(zone.bounds.max.y.raw());

            // Expand by clearance
            let min_gx = min_gx.saturating_sub(clearance_cells);
            let min_gy = min_gy.saturating_sub(clearance_cells);
            let max_gx = (max_gx + clearance_cells).min(self.width.saturating_sub(1));
            let max_gy = (max_gy + clearance_cells).min(self.height.saturating_sub(1));

            for layer_idx in 0..self.layer_count {
                if zone.on_layer(layer_idx) {
                    for gy in min_gy..=max_gy {
                        for gx in min_gx..=max_gx {
                            self.set_cell(gx, gy, layer_idx as usize, CELL_ZONE);
                        }
                    }
                }
            }
        }
    }

    /// Populate locked trace obstacles.
    fn populate_locked_traces(&mut self, world: &mut BoardWorld, clearance_cells: u32) {
        use cypcb_world::components::trace::Trace;

        // Collect trace data to avoid borrow conflict
        let traces: Vec<Trace> = {
            let ecs = world.ecs_mut();
            let mut query = ecs.query::<&Trace>();
            query
                .iter(ecs)
                .filter(|t| t.locked)
                .cloned()
                .collect()
        };

        for trace in &traces {
            if let Some(layer_idx) = layer_to_index(trace.layer) {
                if (layer_idx as u8) >= self.layer_count {
                    continue;
                }
                let half_width_nm = trace.width.raw() / 2;
                let half_width_cells =
                    ((half_width_nm + self.resolution - 1) / self.resolution) as u32;
                let radius_cells = half_width_cells + clearance_cells;

                for seg in &trace.segments {
                    // Rasterize the segment by stepping along it
                    self.rasterize_segment(
                        seg.start.x.raw(),
                        seg.start.y.raw(),
                        seg.end.x.raw(),
                        seg.end.y.raw(),
                        layer_idx,
                        radius_cells,
                        CELL_TRACE,
                    );
                }
            }
        }
    }

    /// Rasterize a line segment onto the grid, marking cells within `radius_cells`.
    #[allow(clippy::too_many_arguments)]
    fn rasterize_segment(
        &mut self,
        x0_nm: i64,
        y0_nm: i64,
        x1_nm: i64,
        y1_nm: i64,
        layer: usize,
        radius_cells: u32,
        flag: u8,
    ) {
        // Step along the segment at grid resolution
        let dx = x1_nm - x0_nm;
        let dy = y1_nm - y0_nm;
        let length_nm = ((dx as f64).powi(2) + (dy as f64).powi(2)).sqrt() as i64;
        let steps = (length_nm / self.resolution).max(1);

        for i in 0..=steps {
            let t = i as f64 / steps as f64;
            let px = x0_nm + (dx as f64 * t) as i64;
            let py = y0_nm + (dy as f64 * t) as i64;

            let gx = self.nm_to_grid_x(px);
            let gy = self.nm_to_grid_y(py);

            self.mark_obstacle(gx, gy, layer, radius_cells, flag);
        }
    }

    // ========================================================================
    // Coordinate conversion
    // ========================================================================

    /// Convert a nanometer X coordinate to a grid X index.
    #[inline]
    pub fn nm_to_grid_x(&self, nm: i64) -> u32 {
        let adjusted = nm - self.origin_x;
        if adjusted < 0 {
            0
        } else {
            ((adjusted / self.resolution) as u32).min(self.width.saturating_sub(1))
        }
    }

    /// Convert a nanometer Y coordinate to a grid Y index.
    #[inline]
    pub fn nm_to_grid_y(&self, nm: i64) -> u32 {
        let adjusted = nm - self.origin_y;
        if adjusted < 0 {
            0
        } else {
            ((adjusted / self.resolution) as u32).min(self.height.saturating_sub(1))
        }
    }

    /// Convert a grid X index back to nanometers (center of cell).
    #[inline]
    pub fn grid_to_nm_x(&self, gx: u32) -> i64 {
        self.origin_x + (gx as i64) * self.resolution + self.resolution / 2
    }

    /// Convert a grid Y index back to nanometers (center of cell).
    #[inline]
    pub fn grid_to_nm_y(&self, gy: u32) -> i64 {
        self.origin_y + (gy as i64) * self.resolution + self.resolution / 2
    }

    /// Convert a nanometer position to grid coordinates.
    #[inline]
    pub fn nm_to_grid(&self, pos: Point) -> (u32, u32) {
        (self.nm_to_grid_x(pos.x.raw()), self.nm_to_grid_y(pos.y.raw()))
    }

    /// Convert grid coordinates to a nanometer position (center of cell).
    #[inline]
    pub fn grid_to_nm(&self, gx: u32, gy: u32) -> Point {
        Point::new(Nm::new(self.grid_to_nm_x(gx)), Nm::new(self.grid_to_nm_y(gy)))
    }

    // ========================================================================
    // Cell access
    // ========================================================================

    /// Check if a cell is free (no obstacles) on the given layer.
    #[inline]
    pub fn is_free(&self, x: u32, y: u32, layer: usize) -> bool {
        if x >= self.width || y >= self.height || layer >= self.layers.len() {
            return false;
        }
        let idx = (y as usize) * (self.width as usize) + (x as usize);
        self.layers[layer][idx] == CELL_FREE
    }

    /// Get the occupancy flags for a cell.
    #[inline]
    pub fn cell(&self, x: u32, y: u32, layer: usize) -> u8 {
        if x >= self.width || y >= self.height || layer >= self.layers.len() {
            return u8::MAX; // Out of bounds = fully blocked
        }
        let idx = (y as usize) * (self.width as usize) + (x as usize);
        self.layers[layer][idx]
    }

    /// Set an occupancy flag on a cell.
    #[inline]
    fn set_cell(&mut self, x: u32, y: u32, layer: usize, flag: u8) {
        if x >= self.width || y >= self.height || layer >= self.layers.len() {
            return;
        }
        let idx = (y as usize) * (self.width as usize) + (x as usize);
        self.layers[layer][idx] |= flag;
    }

    /// Mark a circular area around (cx, cy) as occupied on the given layer.
    pub fn mark_obstacle(&mut self, cx: u32, cy: u32, layer: usize, radius_cells: u32, flag: u8) {
        if layer >= self.layers.len() {
            return;
        }

        let r = radius_cells as i64;
        let r_sq = r * r;

        let min_x = (cx as i64 - r).max(0) as u32;
        let max_x = (cx as i64 + r).min(self.width as i64 - 1) as u32;
        let min_y = (cy as i64 - r).max(0) as u32;
        let max_y = (cy as i64 + r).min(self.height as i64 - 1) as u32;

        for y in min_y..=max_y {
            for x in min_x..=max_x {
                let dx = x as i64 - cx as i64;
                let dy = y as i64 - cy as i64;
                if dx * dx + dy * dy <= r_sq {
                    self.set_cell(x, y, layer, flag);
                }
            }
        }
    }

    /// Mark obstacle given absolute nanometer coordinates.
    fn mark_obstacle_at_nm(
        &mut self,
        nm_x: i64,
        nm_y: i64,
        layer: usize,
        radius_cells: u32,
        flag: u8,
    ) {
        let gx = self.nm_to_grid_x(nm_x);
        let gy = self.nm_to_grid_y(nm_y);
        self.mark_obstacle(gx, gy, layer, radius_cells, flag);
    }

    /// Mark cells along a route for a specific net.
    pub fn mark_route(&mut self, x: u32, y: u32, layer: usize, net_id: u32) {
        if x >= self.width || y >= self.height || layer >= self.layers.len() {
            return;
        }
        let idx = (y as usize) * (self.width as usize) + (x as usize);
        self.layers[layer][idx] |= CELL_TRACE;
        self.net_map[layer][idx] = net_id;
    }

    /// Clear all cells belonging to a specific net (for rip-up).
    pub fn clear_route(&mut self, net_id: u32) {
        for layer in 0..self.layer_count as usize {
            let w = self.width as usize;
            let h = self.height as usize;
            for idx in 0..(w * h) {
                if self.net_map[layer][idx] == net_id {
                    self.net_map[layer][idx] = u32::MAX;
                    // Clear the trace bit but keep other obstacle flags
                    self.layers[layer][idx] &= !CELL_TRACE;
                }
            }
        }
    }

    // ========================================================================
    // Statistics
    // ========================================================================

    /// Get grid dimensions and obstacle statistics.
    pub fn stats(&self) -> GridStats {
        let mut obstacle_count: u64 = 0;
        for layer_data in &self.layers {
            obstacle_count += layer_data.iter().filter(|&&c| c != CELL_FREE).count() as u64;
        }

        GridStats {
            width: self.width,
            height: self.height,
            layers: self.layer_count,
            obstacle_cell_count: obstacle_count,
            resolution_nm: self.resolution,
        }
    }

    /// Grid width in cells.
    #[inline]
    pub fn width(&self) -> u32 {
        self.width
    }

    /// Grid height in cells.
    #[inline]
    pub fn height(&self) -> u32 {
        self.height
    }

    /// Number of routing layers.
    #[inline]
    pub fn layer_count(&self) -> u8 {
        self.layer_count
    }

    /// Grid resolution in nanometers.
    #[inline]
    pub fn resolution(&self) -> i64 {
        self.resolution
    }
}

// ============================================================================
// Helpers
// ============================================================================

/// Convert a `Layer` enum to a routing layer index (0-based).
///
/// Returns `None` for non-copper layers.
fn layer_to_index(layer: Layer) -> Option<usize> {
    match layer {
        Layer::TopCopper => Some(0),
        Layer::BottomCopper => Some(1),
        Layer::Inner(n) => Some(2 + n as usize),
        _ => None,
    }
}

/// Rotate a point around the origin by the given angle in degrees.
fn rotate_point(p: Point, degrees: f64) -> Point {
    if degrees.abs() < 0.001 {
        return p;
    }
    let rad = degrees.to_radians();
    let cos = rad.cos();
    let sin = rad.sin();
    let x = p.x.raw() as f64;
    let y = p.y.raw() as f64;
    Point::new(
        Nm::new((x * cos - y * sin).round() as i64),
        Nm::new((x * sin + y * cos).round() as i64),
    )
}

/// Create a minimal grid for unit testing (no board needed).
#[cfg(test)]
pub(crate) fn make_test_grid(width: u32, height: u32, resolution_nm: i64, layers: u8) -> RoutingGrid {
    let cell_count = (width as usize) * (height as usize);
    RoutingGrid {
        width,
        height,
        resolution: resolution_nm,
        origin_x: 0,
        origin_y: 0,
        layer_count: layers,
        layers: (0..layers).map(|_| vec![CELL_FREE; cell_count]).collect(),
        net_map: (0..layers).map(|_| vec![u32::MAX; cell_count]).collect(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use cypcb_core::Point;

    fn make_test_grid(width: u32, height: u32, resolution_nm: i64, layers: u8) -> RoutingGrid {
        let cell_count = (width as usize) * (height as usize);
        RoutingGrid {
            width,
            height,
            resolution: resolution_nm,
            origin_x: 0,
            origin_y: 0,
            layer_count: layers,
            layers: (0..layers).map(|_| vec![CELL_FREE; cell_count]).collect(),
            net_map: (0..layers).map(|_| vec![u32::MAX; cell_count]).collect(),
        }
    }

    #[test]
    fn coordinate_round_trip_accuracy() {
        // Grid: 100 cells wide, resolution = 63500 nm (63.5µm ≈ min_clearance/2)
        let grid = make_test_grid(100, 100, 63_500, 2);

        // Test several positions
        for &nm_x in &[0i64, 63_500, 500_000, 3_175_000, 6_300_000] {
            let gx = grid.nm_to_grid_x(nm_x);
            let back = grid.grid_to_nm_x(gx);
            let error = (back - nm_x).abs();
            // Round-trip should be within 1 grid cell
            assert!(
                error <= grid.resolution,
                "Round-trip error {error} exceeds resolution {} for nm_x={nm_x}",
                grid.resolution
            );
        }
    }

    #[test]
    fn coordinate_round_trip_point() {
        let grid = make_test_grid(200, 200, 50_000, 2);

        let original = Point::from_mm(5.0, 3.0);
        let (gx, gy) = grid.nm_to_grid(original);
        let back = grid.grid_to_nm(gx, gy);

        let err_x = (back.x.raw() - original.x.raw()).abs();
        let err_y = (back.y.raw() - original.y.raw()).abs();

        assert!(err_x <= grid.resolution, "X round-trip error {err_x} > {}", grid.resolution);
        assert!(err_y <= grid.resolution, "Y round-trip error {err_y} > {}", grid.resolution);
    }

    #[test]
    fn obstacle_marking_circular() {
        let mut grid = make_test_grid(20, 20, 100_000, 1);

        // Mark obstacle at center (10, 10) with radius 3
        grid.mark_obstacle(10, 10, 0, 3, CELL_PAD);

        // Center should be marked
        assert!(!grid.is_free(10, 10, 0));
        assert_eq!(grid.cell(10, 10, 0) & CELL_PAD, CELL_PAD);

        // Cell at radius 3 (along axis) should be marked
        assert!(!grid.is_free(13, 10, 0));
        assert!(!grid.is_free(7, 10, 0));

        // Cell at radius 4 along axis should be free (outside radius 3)
        assert!(grid.is_free(14, 10, 0));

        // Corner cell at (13, 13): distance = sqrt(9+9) ≈ 4.24 > 3, should be free
        assert!(grid.is_free(13, 13, 0));
    }

    #[test]
    fn clearance_bloat_extends_obstacle() {
        let mut grid = make_test_grid(30, 30, 100_000, 1);

        // Mark pad with radius 2, plus clearance 3 = total radius 5
        let pad_radius = 2u32;
        let clearance = 3u32;
        grid.mark_obstacle(15, 15, 0, pad_radius + clearance, CELL_PAD);

        // Cell at distance 4 from center should be blocked (within 5)
        assert!(!grid.is_free(19, 15, 0)); // distance 4

        // Cell at distance 6 along axis should be free (outside 5)
        assert!(grid.is_free(21, 15, 0));
    }

    #[test]
    fn layer_isolation() {
        let mut grid = make_test_grid(20, 20, 100_000, 2);

        // Mark obstacle only on layer 0
        grid.mark_obstacle(10, 10, 0, 2, CELL_PAD);

        // Layer 0 should be blocked
        assert!(!grid.is_free(10, 10, 0));

        // Layer 1 should still be free
        assert!(grid.is_free(10, 10, 1));
    }

    #[test]
    fn is_free_out_of_bounds() {
        let grid = make_test_grid(10, 10, 100_000, 2);

        // Out of bounds should return false (not free)
        assert!(!grid.is_free(10, 0, 0)); // x == width
        assert!(!grid.is_free(0, 10, 0)); // y == height
        assert!(!grid.is_free(0, 0, 2)); // layer == layer_count
        assert!(!grid.is_free(100, 100, 0));
    }

    #[test]
    fn mark_and_clear_route() {
        let mut grid = make_test_grid(10, 10, 100_000, 1);

        // Mark a route for net 42
        grid.mark_route(3, 3, 0, 42);
        grid.mark_route(4, 3, 0, 42);
        grid.mark_route(5, 3, 0, 42);

        assert!(!grid.is_free(3, 3, 0));
        assert!(!grid.is_free(4, 3, 0));
        assert!(!grid.is_free(5, 3, 0));

        // Clear net 42
        grid.clear_route(42);

        assert!(grid.is_free(3, 3, 0));
        assert!(grid.is_free(4, 3, 0));
        assert!(grid.is_free(5, 3, 0));
    }

    #[test]
    fn clear_route_preserves_other_obstacles() {
        let mut grid = make_test_grid(10, 10, 100_000, 1);

        // Mark a pad at (5, 5)
        grid.set_cell(5, 5, 0, CELL_PAD);

        // Mark a route over it for net 7
        grid.mark_route(5, 5, 0, 7);

        // Clear net 7's route
        grid.clear_route(7);

        // The pad should still be there
        assert!(!grid.is_free(5, 5, 0));
        assert_eq!(grid.cell(5, 5, 0) & CELL_PAD, CELL_PAD);
    }

    #[test]
    fn stats_counts_obstacles() {
        let mut grid = make_test_grid(10, 10, 100_000, 2);

        // Initially all free
        let stats = grid.stats();
        assert_eq!(stats.obstacle_cell_count, 0);
        assert_eq!(stats.width, 10);
        assert_eq!(stats.height, 10);
        assert_eq!(stats.layers, 2);

        // Mark some cells
        grid.set_cell(0, 0, 0, CELL_PAD);
        grid.set_cell(1, 1, 1, CELL_ZONE);

        let stats = grid.stats();
        assert_eq!(stats.obstacle_cell_count, 2);
    }

    #[test]
    fn layer_to_index_mapping() {
        assert_eq!(layer_to_index(Layer::TopCopper), Some(0));
        assert_eq!(layer_to_index(Layer::BottomCopper), Some(1));
        assert_eq!(layer_to_index(Layer::Inner(0)), Some(2));
        assert_eq!(layer_to_index(Layer::Inner(1)), Some(3));
        assert_eq!(layer_to_index(Layer::TopSilk), None);
        assert_eq!(layer_to_index(Layer::Outline), None);
    }

    #[test]
    fn rotate_point_90_degrees() {
        let p = Point::from_mm(1.0, 0.0);
        let rotated = rotate_point(p, 90.0);
        // After 90° rotation: (1, 0) -> (0, 1)
        assert!(
            (rotated.x.raw()).abs() < 1000, // within 1µm
            "x should be ~0, got {}",
            rotated.x.raw()
        );
        assert!(
            (rotated.y.raw() - 1_000_000).abs() < 1000,
            "y should be ~1mm, got {}",
            rotated.y.raw()
        );
    }

    #[test]
    fn rotate_point_zero_is_identity() {
        let p = Point::from_mm(3.5, 7.2);
        let rotated = rotate_point(p, 0.0);
        assert_eq!(rotated.x.raw(), p.x.raw());
        assert_eq!(rotated.y.raw(), p.y.raw());
    }
}

//! A* pathfinder for PCB routing on a discretized grid.
//!
//! Uses the `pathfinding` crate's [`astar`] implementation with a
//! PCB-aware cost function from [`RoutingCost`]. The pathfinder operates
//! on a single net at a time, finding a path between two pad positions
//! that may cross layers via vias.
//!
//! # Grid Nodes
//!
//! A [`GridNode`] is `(grid_x, grid_y, layer_index)`. The pathfinder
//! generates 8-directional neighbors on the same layer plus vertical
//! (via) transitions to adjacent layers at the current position.

use crate::cost::RoutingCost;
use crate::grid::RoutingGrid;
use pathfinding::directed::astar::astar;

/// A position in the routing grid: `(grid_x, grid_y, layer_index)`.
///
/// - `grid_x`, `grid_y`: cell coordinates (0-indexed)
/// - `layer_index`: copper layer (0 = top, 1 = bottom, 2+ = inner)
pub type GridNode = (u16, u16, u8);

/// 8-directional movement offsets: N, NE, E, SE, S, SW, W, NW.
const DIRECTIONS: [(i32, i32); 8] = [
    (0, -1),  // N
    (1, -1),  // NE
    (1, 0),   // E
    (1, 1),   // SE
    (0, 1),   // S
    (-1, 1),  // SW
    (-1, 0),  // W
    (-1, -1), // NW
];

/// Find a path between two grid nodes using A* search.
///
/// The path traverses the routing grid using 8-directional movement
/// on each layer and via transitions between layers. The cost function
/// penalizes vias, non-preferred layers, and diagonal movement.
///
/// After a path is found, all path cells are marked as occupied on the
/// grid so subsequent routing calls will route around them.
///
/// # Arguments
///
/// * `grid` - The routing grid with occupancy data
/// * `start` - Source pad position as a grid node
/// * `end` - Target pad position as a grid node
/// * `cost` - PCB-aware cost function
/// * `any_end_layer` - If `true`, the path can end on any layer at the
///   goal (x, y) position (for through-hole pads). If `false`, must match
///   the exact layer of `end`.
///
/// # Returns
///
/// The path as a `Vec<GridNode>` (including start and end), or `None`
/// if no path exists. On success, path cells are marked on the grid.
pub fn find_path(
    grid: &mut RoutingGrid,
    start: GridNode,
    end: GridNode,
    cost: &RoutingCost,
    any_end_layer: bool,
) -> Option<Vec<GridNode>> {
    let _span = tracing::debug_span!(
        "find_path",
        net_id = cost.net_id(),
        start_x = start.0,
        start_y = start.1,
        start_layer = start.2,
        end_x = end.0,
        end_y = end.1,
        end_layer = end.2,
    )
    .entered();

    let grid_w = grid.width();
    let grid_h = grid.height();
    let layer_count = grid.layer_count();

    // Validate start/end are within grid bounds
    if start.0 as u32 >= grid_w
        || start.1 as u32 >= grid_h
        || start.2 >= layer_count
        || end.0 as u32 >= grid_w
        || end.1 as u32 >= grid_h
        || end.2 >= layer_count
    {
        tracing::warn!(
            grid_w,
            grid_h,
            layer_count,
            "find_path: start or end out of grid bounds"
        );
        return None;
    }

    let net_id = cost.net_id();

    // Success condition: reached goal position (and optionally correct layer)
    let success = |node: &GridNode| -> bool {
        node.0 == end.0 && node.1 == end.1 && (any_end_layer || node.2 == end.2)
    };

    // Successor function: 8 neighbors on same layer + via transitions
    let successors = |node: &GridNode| -> Vec<(GridNode, u64)> {
        let mut neighbors = Vec::with_capacity(10);
        let (nx, ny, nl) = *node;

        // 8-directional movement on the same layer
        for &(dx, dy) in &DIRECTIONS {
            let new_x = nx as i32 + dx;
            let new_y = ny as i32 + dy;

            if new_x < 0 || new_y < 0 {
                continue;
            }
            let ux = new_x as u32;
            let uy = new_y as u32;
            if ux >= grid_w || uy >= grid_h {
                continue;
            }

            // Check if the target cell is free (or is our destination pad)
            let target = (ux as u16, uy as u16, nl);
            if grid.is_free(ux, uy, nl as usize) || success(&target) {
                let c = cost.neighbor_cost(*node, target);
                // Convert f64 cost to u64 with 3 decimal digits of precision
                neighbors.push((target, float_to_int_cost(c)));
            }
        }

        // Via transitions: same (x,y), different layer
        for target_layer in 0..layer_count {
            if target_layer == nl {
                continue;
            }
            let target = (nx, ny, target_layer);
            if grid.is_free(nx as u32, ny as u32, target_layer as usize) || success(&target) {
                let c = cost.neighbor_cost(*node, target);
                neighbors.push((target, float_to_int_cost(c)));
            }
        }

        neighbors
    };

    // Heuristic function (must return u64 matching cost scale)
    let heuristic = |node: &GridNode| -> u64 {
        float_to_int_cost(cost.heuristic(*node, end))
    };

    // Run A*
    let result = astar(&start, successors, heuristic, success);

    match result {
        Some((path, _total_cost)) => {
            let path_len = path.len();
            let via_count = path.windows(2).filter(|w| w[0].2 != w[1].2).count();

            tracing::debug!(
                path_length = path_len,
                via_count,
                "Path found"
            );

            // Mark all path cells as occupied on the grid
            for node in &path {
                grid.mark_route(node.0 as u32, node.1 as u32, node.2 as usize, net_id);
            }

            Some(path)
        }
        None => {
            let stats = grid.stats();
            tracing::warn!(
                start_x = start.0,
                start_y = start.1,
                start_layer = start.2,
                end_x = end.0,
                end_y = end.1,
                end_layer = end.2,
                grid_width = stats.width,
                grid_height = stats.height,
                obstacle_count = stats.obstacle_cell_count,
                "No path found"
            );
            None
        }
    }
}

/// Convert an f64 cost to u64 with milli-unit precision.
///
/// This lets us use the `pathfinding` crate's integer-cost A* while
/// preserving enough precision for √2 diagonal costs.
#[inline]
fn float_to_int_cost(f: f64) -> u64 {
    (f * 1000.0).round() as u64
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::grid::{make_test_grid, CELL_OBSTACLE};
    use cypcb_core::Nm;
    use cypcb_rules::signal_class::{SignalClass, SignalClassConstraints};
    use cypcb_rules::{DesignConstraints, RoutingRuleSet};

    /// Minimal rules for pathfinder tests.
    struct TestRules {
        base: DesignConstraints,
    }

    impl TestRules {
        fn new() -> Self {
            Self {
                base: DesignConstraints::default(),
            }
        }
    }

    impl RoutingRuleSet for TestRules {
        fn constraints_for_net(&self, _net_id: u32) -> &DesignConstraints {
            &self.base
        }
        fn constraints_for_class(&self, class: SignalClass) -> SignalClassConstraints {
            class.default_constraints()
        }
        fn via_cost(&self, from_layer: u8, to_layer: u8) -> f64 {
            let span = (from_layer as i16 - to_layer as i16).unsigned_abs() as f64;
            span * 2.0
        }
        fn layer_change_cost(&self, layer: u8) -> f64 {
            if layer == 0 {
                0.1
            } else {
                0.5
            }
        }
        fn clearance_between(&self, _net_a: u32, _net_b: u32) -> Nm {
            self.base.min_clearance
        }
    }

    #[test]
    fn route_on_empty_grid() {
        let mut grid = make_test_grid(20, 20, 100_000, 1);
        let rules = TestRules::new();
        let cost = RoutingCost::new(&rules, 1, 1.0);

        let path = find_path(&mut grid, (0, 0, 0), (19, 19, 0), &cost, false);
        assert!(path.is_some(), "Should find path on empty grid");

        let path = path.unwrap();
        // Path should start and end at the right places
        assert_eq!(path.first().unwrap(), &(0, 0, 0));
        assert_eq!(path.last().unwrap(), &(19, 19, 0));

        // Diagonal path should be ~20 steps (19 diagonal moves)
        // Reasonable range: 19-30 steps
        assert!(
            path.len() >= 19 && path.len() <= 30,
            "Path length {} seems unreasonable for 20x20 grid",
            path.len()
        );

        // All moves should be adjacent (1 cell max in each direction)
        for w in path.windows(2) {
            let dx = (w[0].0 as i32 - w[1].0 as i32).abs();
            let dy = (w[0].1 as i32 - w[1].1 as i32).abs();
            assert!(dx <= 1 && dy <= 1, "Non-adjacent move: {:?} -> {:?}", w[0], w[1]);
        }
    }

    #[test]
    fn route_around_l_shaped_obstacle() {
        let mut grid = make_test_grid(20, 20, 100_000, 1);
        let rules = TestRules::new();
        let cost = RoutingCost::new(&rules, 1, 1.0);

        // Create L-shaped obstacle blocking the direct path from (2,2) to (17,17)
        // Vertical wall from (10, 0) to (10, 14)
        for y in 0..15u32 {
            grid.mark_obstacle(10, y, 0, 0, CELL_OBSTACLE);
        }
        // Horizontal wall from (10, 14) to (20, 14)
        for x in 10..20u32 {
            grid.mark_obstacle(x, 14, 0, 0, CELL_OBSTACLE);
        }

        let path = find_path(&mut grid, (2, 2, 0), (17, 17, 0), &cost, false);
        assert!(path.is_some(), "Should find path around L-shaped obstacle");

        let path = path.unwrap();
        // Verify no path cell overlaps with obstacle cells
        for node in &path {
            assert!(
                !grid_cell_has_obstacle(&grid, node, CELL_OBSTACLE),
                "Path crosses obstacle at {:?}",
                node
            );
        }
    }

    #[test]
    fn route_with_via_between_layers() {
        let mut grid = make_test_grid(20, 20, 100_000, 2);
        let rules = TestRules::new();
        let cost = RoutingCost::new(&rules, 1, 1.0);

        // Block the direct path on layer 0 with a wall
        for x in 0..20u32 {
            grid.mark_obstacle(x, 10, 0, 0, CELL_OBSTACLE);
        }
        // Layer 1 is clear

        // Route from top-left on layer 0 to bottom-right on layer 0
        // Must go through layer 1 to bypass the wall
        let path = find_path(&mut grid, (5, 5, 0), (5, 15, 0), &cost, false);
        assert!(path.is_some(), "Should find path using via to bypass wall");

        let path = path.unwrap();
        // Verify the path includes at least one layer transition
        let via_count = path.windows(2).filter(|w| w[0].2 != w[1].2).count();
        assert!(
            via_count >= 2,
            "Path should have at least 2 layer transitions (down and back up), got {via_count}"
        );

        // Verify start and end layers are correct
        assert_eq!(path.first().unwrap().2, 0, "Should start on layer 0");
        assert_eq!(path.last().unwrap().2, 0, "Should end on layer 0");
    }

    #[test]
    fn route_impossible_returns_none() {
        let mut grid = make_test_grid(10, 10, 100_000, 1);
        let rules = TestRules::new();
        let cost = RoutingCost::new(&rules, 1, 1.0);

        // Completely surround the target with obstacles
        let target = (7u32, 7u32);
        for dx in -1i32..=1 {
            for dy in -1i32..=1 {
                if dx == 0 && dy == 0 {
                    continue;
                }
                let x = (target.0 as i32 + dx) as u32;
                let y = (target.1 as i32 + dy) as u32;
                grid.mark_obstacle(x, y, 0, 0, CELL_OBSTACLE);
            }
        }
        // Also block the target cell itself
        grid.mark_obstacle(target.0, target.1, 0, 0, CELL_OBSTACLE);

        let path = find_path(
            &mut grid,
            (0, 0, 0),
            (target.0 as u16, target.1 as u16, 0),
            &cost,
            false,
        );
        assert!(path.is_none(), "Should return None when target is blocked");
    }

    #[test]
    fn path_cells_marked_as_occupied() {
        let mut grid = make_test_grid(10, 10, 100_000, 1);
        let rules = TestRules::new();
        let cost = RoutingCost::new(&rules, 42, 1.0);

        let path = find_path(&mut grid, (0, 0, 0), (5, 0, 0), &cost, false);
        assert!(path.is_some());

        let path = path.unwrap();
        // After routing, path cells should no longer be free
        for node in &path {
            assert!(
                !grid.is_free(node.0 as u32, node.1 as u32, node.2 as usize),
                "Path cell {:?} should be marked as occupied",
                node
            );
        }
    }

    #[test]
    fn any_end_layer_mode() {
        let mut grid = make_test_grid(10, 10, 100_000, 2);
        let rules = TestRules::new();
        let cost = RoutingCost::new(&rules, 1, 1.0);

        // With any_end_layer = true, path can end on any layer
        let path = find_path(&mut grid, (0, 0, 0), (5, 5, 1), &cost, true);
        assert!(path.is_some());
        let path = path.unwrap();
        let last = path.last().unwrap();
        assert_eq!(last.0, 5);
        assert_eq!(last.1, 5);
        // Layer can be anything (0 or 1)
    }

    /// Helper: check if a grid cell has a specific obstacle flag set.
    /// We check the raw cell value, not is_free(), because is_free checks all flags.
    fn grid_cell_has_obstacle(grid: &RoutingGrid, node: &GridNode, flag: u8) -> bool {
        let cell = grid.cell(node.0 as u32, node.1 as u32, node.2 as usize);
        (cell & flag) != 0
    }
}

//! PCB-aware cost function for A* pathfinding.
//!
//! [`RoutingCost`] wraps the design rules to provide movement costs that
//! account for via transitions, layer preference, diagonal routing, and
//! clearance concerns. The heuristic uses 3D octile distance for admissibility.

use crate::pathfinder::GridNode;
use cypcb_rules::RoutingRuleSet;

/// Square root of 2, cached for diagonal movement cost.
const SQRT2: f64 = std::f64::consts::SQRT_2;

/// PCB-aware cost calculator for A* search.
///
/// Holds a reference to the design rules and the net currently being routed.
/// All cost methods are pure functions of the node positions and rules — the
/// grid itself is not consulted here (that's the pathfinder's job when
/// generating successors).
pub struct RoutingCost<'a> {
    /// Design rules for via cost, layer preference, clearance values.
    rules: &'a dyn RoutingRuleSet,
    /// The net being routed — used for net-specific constraint lookup.
    net_id: u32,
    /// Precomputed minimum via cost across all layer pairs (for heuristic).
    min_via_cost: f64,
    /// Config-driven multiplier for via cost.
    via_cost_multiplier: f64,
}

impl<'a> RoutingCost<'a> {
    /// Create a new cost calculator for routing a specific net.
    pub fn new(rules: &'a dyn RoutingRuleSet, net_id: u32, via_cost_multiplier: f64) -> Self {
        // Precompute the minimum via cost for admissible heuristic.
        // Sample a few common layer pairs.
        let mut min_via = f64::MAX;
        for from in 0..4u8 {
            for to in 0..4u8 {
                if from != to {
                    let c = rules.via_cost(from, to);
                    if c < min_via {
                        min_via = c;
                    }
                }
            }
        }
        if min_via == f64::MAX {
            min_via = 1.0; // fallback
        }

        Self {
            rules,
            net_id,
            min_via_cost: min_via * via_cost_multiplier,
            via_cost_multiplier,
        }
    }

    /// Cost of moving from one grid node to an adjacent node.
    ///
    /// Components:
    /// - **Base movement**: 1.0 for cardinal (N/S/E/W), √2 for diagonal
    /// - **Layer change**: via cost from rules if layers differ
    /// - **Layer preference**: small bias from `layer_change_cost()` on destination layer
    ///
    /// The pathfinder guarantees `from` and `to` are adjacent (1 cell apart
    /// in each axis, or same position with a layer change).
    pub fn neighbor_cost(&self, from: GridNode, to: GridNode) -> f64 {
        let dx = (from.0 as i32 - to.0 as i32).unsigned_abs();
        let dy = (from.1 as i32 - to.1 as i32).unsigned_abs();

        let mut cost = if from.2 != to.2 {
            // Layer transition (via) — position is same, only layer changes
            self.rules.via_cost(from.2, to.2) * self.via_cost_multiplier
        } else if dx == 1 && dy == 1 {
            // Diagonal move
            SQRT2
        } else {
            // Cardinal move (dx + dy == 1)
            1.0
        };

        // Add a small layer-preference bias on the destination layer
        // Scale it down so it doesn't dominate movement cost
        cost += self.rules.layer_change_cost(to.2) * 0.1;

        cost
    }

    /// Admissible heuristic: 3D octile distance.
    ///
    /// On each layer: `max(|dx|, |dy|) + (√2 - 1) * min(|dx|, |dy|)`
    /// Plus minimum via cost per layer transition needed.
    ///
    /// This never overestimates the true cost, so A* remains optimal.
    pub fn heuristic(&self, current: GridNode, goal: GridNode) -> f64 {
        let dx = (current.0 as i32 - goal.0 as i32).unsigned_abs() as f64;
        let dy = (current.1 as i32 - goal.1 as i32).unsigned_abs() as f64;
        let layer_diff = (current.2 as i32 - goal.2 as i32).unsigned_abs() as f64;

        let dmin = dx.min(dy);
        let dmax = dx.max(dy);

        // 2D octile distance + via cost for layer changes
        dmax + (SQRT2 - 1.0) * dmin + self.min_via_cost * layer_diff
    }

    /// Get the net ID this cost function is configured for.
    pub fn net_id(&self) -> u32 {
        self.net_id
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::pathfinder::GridNode;
    use cypcb_core::Nm;
    use cypcb_rules::signal_class::{SignalClass, SignalClassConstraints};
    use cypcb_rules::{DesignConstraints, RoutingRuleSet};

    struct TestRules {
        base: DesignConstraints,
    }

    impl TestRules {
        fn new() -> Self {
            Self {
                base: DesignConstraints::default(),
            }
        }
    }

    impl RoutingRuleSet for TestRules {
        fn constraints_for_net(&self, _net_id: u32) -> &DesignConstraints {
            &self.base
        }
        fn constraints_for_class(&self, class: SignalClass) -> SignalClassConstraints {
            class.default_constraints()
        }
        fn via_cost(&self, from_layer: u8, to_layer: u8) -> f64 {
            let span = (from_layer as i16 - to_layer as i16).unsigned_abs() as f64;
            span * 2.0
        }
        fn layer_change_cost(&self, layer: u8) -> f64 {
            if layer == 0 {
                0.1
            } else {
                0.5
            }
        }
        fn clearance_between(&self, _net_a: u32, _net_b: u32) -> Nm {
            self.base.min_clearance
        }
    }

    #[test]
    fn cardinal_move_costs_one() {
        let rules = TestRules::new();
        let cost = RoutingCost::new(&rules, 0, 1.0);
        let from: GridNode = (5, 5, 0);
        let to: GridNode = (6, 5, 0);
        let c = cost.neighbor_cost(from, to);
        // Base 1.0 + small layer preference
        assert!(c >= 1.0 && c < 1.5, "Cardinal cost: {c}");
    }

    #[test]
    fn diagonal_move_costs_sqrt2() {
        let rules = TestRules::new();
        let cost = RoutingCost::new(&rules, 0, 1.0);
        let from: GridNode = (5, 5, 0);
        let to: GridNode = (6, 6, 0);
        let c = cost.neighbor_cost(from, to);
        assert!(c >= SQRT2 && c < SQRT2 + 0.5, "Diagonal cost: {c}");
    }

    #[test]
    fn via_transition_costs_more_than_movement() {
        let rules = TestRules::new();
        let cost = RoutingCost::new(&rules, 0, 1.0);
        let cardinal = cost.neighbor_cost((5, 5, 0), (6, 5, 0));
        let via = cost.neighbor_cost((5, 5, 0), (5, 5, 1));
        assert!(via > cardinal, "Via cost {via} should exceed cardinal {cardinal}");
    }

    #[test]
    fn heuristic_is_admissible_straight_line() {
        let rules = TestRules::new();
        let cost = RoutingCost::new(&rules, 0, 1.0);
        // Straight 10-cell path on same layer
        let h = cost.heuristic((0, 0, 0), (10, 0, 0));
        // Heuristic should be <= actual path cost (10 cardinal moves = 10.0)
        assert!(h <= 10.0 + 1e-9, "Heuristic {h} should be <= 10.0");
    }

    #[test]
    fn heuristic_diagonal_path() {
        let rules = TestRules::new();
        let cost = RoutingCost::new(&rules, 0, 1.0);
        // Diagonal 5-cell path
        let h = cost.heuristic((0, 0, 0), (5, 5, 0));
        // Pure diagonal: 5 * √2 ≈ 7.07
        let expected = 5.0 * SQRT2;
        assert!(
            (h - expected).abs() < 1e-9,
            "Heuristic {h} should be {expected}"
        );
    }

    #[test]
    fn heuristic_includes_layer_cost() {
        let rules = TestRules::new();
        let cost = RoutingCost::new(&rules, 0, 1.0);
        let same_layer = cost.heuristic((0, 0, 0), (5, 0, 0));
        let diff_layer = cost.heuristic((0, 0, 0), (5, 0, 1));
        assert!(
            diff_layer > same_layer,
            "Cross-layer heuristic {diff_layer} should exceed same-layer {same_layer}"
        );
    }

    #[test]
    fn straight_path_cheaper_than_zigzag() {
        let rules = TestRules::new();
        let cost = RoutingCost::new(&rules, 0, 1.0);

        // Straight path: (0,0) -> (1,0) -> (2,0) -> (3,0) -> (4,0)
        let straight_cost: f64 = [(0u16, 0u16), (1, 0), (2, 0), (3, 0)]
            .windows(2)
            .map(|w| cost.neighbor_cost((w[0].0, w[0].1, 0), (w[1].0, w[1].1, 0)))
            .sum();

        // Zigzag path: (0,0) -> (1,1) -> (2,0) -> (3,1) -> (4,0)
        let zigzag_cost: f64 = [(0u16, 0u16), (1, 1), (2, 0), (3, 1)]
            .windows(2)
            .map(|w| cost.neighbor_cost((w[0].0, w[0].1, 0), (w[1].0, w[1].1, 0)))
            .sum();

        assert!(
            straight_cost < zigzag_cost,
            "Straight {straight_cost} should be cheaper than zigzag {zigzag_cost}"
        );
    }
}

//! Electrical components for board entities.
//!
//! These components represent the electrical properties of PCB elements:
//! net connections, reference designators, component values, and pin mappings.

use bevy_ecs::prelude::*;
use serde::{Deserialize, Serialize};

/// Unique identifier for a net (interned from name).
///
/// Net names are interned to integer IDs at parse time for efficient
/// comparison and storage. The mapping is maintained by a NetRegistry.
///
/// # Examples
///
/// ```
/// use cypcb_world::NetId;
///
/// let vcc = NetId(0);
/// let gnd = NetId(1);
/// assert_ne!(vcc, gnd);
/// ```
#[derive(Component, Debug, Clone, Copy, PartialEq, Eq, Hash, Default, Serialize, Deserialize)]
pub struct NetId(pub u32);

impl NetId {
    /// Create a new NetId.
    #[inline]
    pub const fn new(id: u32) -> Self {
        NetId(id)
    }

    /// Get the raw ID value.
    #[inline]
    pub const fn id(&self) -> u32 {
        self.0
    }
}

impl std::fmt::Display for NetId {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "Net({})", self.0)
    }
}

/// Reference designator for a component (R1, C1, U1, etc.).
///
/// Reference designators uniquely identify components on a board.
/// They follow standard conventions:
/// - R: Resistors
/// - C: Capacitors
/// - L: Inductors
/// - U: ICs
/// - LED: LEDs
/// - J/P: Connectors
///
/// # Examples
///
/// ```
/// use cypcb_world::RefDes;
///
/// let r1 = RefDes::new("R1");
/// assert_eq!(r1.as_str(), "R1");
/// ```
#[derive(Component, Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct RefDes(pub String);

impl RefDes {
    /// Create a new reference designator.
    #[inline]
    pub fn new(refdes: impl Into<String>) -> Self {
        RefDes(refdes.into())
    }

    /// Get the reference designator as a string slice.
    #[inline]
    pub fn as_str(&self) -> &str {
        &self.0
    }

    /// Extract the prefix (letters) from the reference designator.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_world::RefDes;
    ///
    /// assert_eq!(RefDes::new("R1").prefix(), "R");
    /// assert_eq!(RefDes::new("LED2").prefix(), "LED");
    /// assert_eq!(RefDes::new("U100").prefix(), "U");
    /// ```
    pub fn prefix(&self) -> &str {
        let end = self.0.find(|c: char| c.is_ascii_digit()).unwrap_or(self.0.len());
        &self.0[..end]
    }

    /// Extract the number suffix from the reference designator.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_world::RefDes;
    ///
    /// assert_eq!(RefDes::new("R1").number(), Some(1));
    /// assert_eq!(RefDes::new("LED2").number(), Some(2));
    /// assert_eq!(RefDes::new("U100").number(), Some(100));
    /// assert_eq!(RefDes::new("TEST").number(), None);
    /// ```
    pub fn number(&self) -> Option<u32> {
        let start = self.0.find(|c: char| c.is_ascii_digit())?;
        self.0[start..].parse().ok()
    }
}

impl std::fmt::Display for RefDes {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.0)
    }
}

impl From<&str> for RefDes {
    fn from(s: &str) -> Self {
        RefDes::new(s)
    }
}

impl From<String> for RefDes {
    fn from(s: String) -> Self {
        RefDes(s)
    }
}

/// Component value (10k, 100nF, ATmega328P).
///
/// Stores the value string for a component. This can be:
/// - Resistance values: "10k", "4.7k", "1M"
/// - Capacitance values: "100nF", "10uF", "1pF"
/// - IC part numbers: "ATmega328P", "STM32F103"
/// - Any other identifying string
///
/// # Examples
///
/// ```
/// use cypcb_world::Value;
///
/// let resistor_value = Value::new("10k");
/// let cap_value = Value::new("100nF");
/// let ic_value = Value::new("ATmega328P");
/// ```
#[derive(Component, Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct Value(pub String);

impl Value {
    /// Create a new value.
    #[inline]
    pub fn new(value: impl Into<String>) -> Self {
        Value(value.into())
    }

    /// Get the value as a string slice.
    #[inline]
    pub fn as_str(&self) -> &str {
        &self.0
    }
}

impl std::fmt::Display for Value {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.0)
    }
}

impl From<&str> for Value {
    fn from(s: &str) -> Self {
        Value::new(s)
    }
}

impl From<String> for Value {
    fn from(s: String) -> Self {
        Value(s)
    }
}

/// A single pin-to-net connection.
///
/// Maps a pin identifier to a net ID. Pin identifiers can be:
/// - Numbers: "1", "2" (for simple components)
/// - Names: "VCC", "GND", "anode", "cathode"
#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub struct PinConnection {
    /// The pin identifier (number or name).
    pub pin: String,
    /// The net this pin connects to.
    pub net: NetId,
}

impl PinConnection {
    /// Create a new pin connection.
    #[inline]
    pub fn new(pin: impl Into<String>, net: NetId) -> Self {
        PinConnection {
            pin: pin.into(),
            net,
        }
    }
}

/// Collection of pin-to-net connections for a component.
///
/// Stores all the net connections for a single component.
/// Used to determine which pins connect to which nets.
///
/// # Examples
///
/// ```
/// use cypcb_world::{NetConnections, NetId, PinConnection};
///
/// let mut conns = NetConnections::new();
/// conns.add(PinConnection::new("1", NetId(0)));  // Pin 1 -> VCC
/// conns.add(PinConnection::new("2", NetId(1)));  // Pin 2 -> GND
///
/// assert!(conns.contains_net(NetId(0)));
/// assert!(conns.pin_net("1") == Some(NetId(0)));
/// ```
#[derive(Component, Debug, Clone, PartialEq, Eq, Default, Serialize, Deserialize)]
pub struct NetConnections {
    connections: Vec<PinConnection>,
}

impl NetConnections {
    /// Create an empty net connections collection.
    #[inline]
    pub fn new() -> Self {
        NetConnections {
            connections: Vec::new(),
        }
    }

    /// Create with pre-allocated capacity.
    #[inline]
    pub fn with_capacity(capacity: usize) -> Self {
        NetConnections {
            connections: Vec::with_capacity(capacity),
        }
    }

    /// Add a pin connection.
    #[inline]
    pub fn add(&mut self, connection: PinConnection) {
        self.connections.push(connection);
    }

    /// Check if any pin connects to the given net.
    pub fn contains_net(&self, net: NetId) -> bool {
        self.connections.iter().any(|c| c.net == net)
    }

    /// Get the net for a specific pin.
    pub fn pin_net(&self, pin: &str) -> Option<NetId> {
        self.connections.iter().find(|c| c.pin == pin).map(|c| c.net)
    }

    /// Get all pins connected to a specific net.
    pub fn pins_on_net(&self, net: NetId) -> impl Iterator<Item = &str> {
        self.connections
            .iter()
            .filter(move |c| c.net == net)
            .map(|c| c.pin.as_str())
    }

    /// Iterate over all connections.
    #[inline]
    pub fn iter(&self) -> impl Iterator<Item = &PinConnection> {
        self.connections.iter()
    }

    /// Number of connections.
    #[inline]
    pub fn len(&self) -> usize {
        self.connections.len()
    }

    /// Check if empty.
    #[inline]
    pub fn is_empty(&self) -> bool {
        self.connections.is_empty()
    }
}

impl IntoIterator for NetConnections {
    type Item = PinConnection;
    type IntoIter = std::vec::IntoIter<PinConnection>;

    fn into_iter(self) -> Self::IntoIter {
        self.connections.into_iter()
    }
}

impl<'a> IntoIterator for &'a NetConnections {
    type Item = &'a PinConnection;
    type IntoIter = std::slice::Iter<'a, PinConnection>;

    fn into_iter(self) -> Self::IntoIter {
        self.connections.iter()
    }
}

