#[test]
fn ripup_triggers_on_blocked_path() {
    use crate::grid::make_test_grid;

    // 30x10 grid, 1 layer
    let mut grid = make_test_grid(30, 10, 100_000, 1);
    let rules = TestRules::new();
    let config = AutorouteConfig {
        max_ripup_iterations: 3,
        ..Default::default()
    };

    // Route net 1 horizontally through the middle
    let cost1 = RoutingCost::new(&rules, 1, 1.0);
    let path1 = find_path(&mut grid, (0, 5, 0), (29, 5, 0), &cost1, false);
    assert!(path1.is_some(), "Net 1 should route on empty grid");

    // Build a ratsnest with two nets
    let net1 = NetRoute {
        net_id: NetId::new(1),
        net_name: "NET1".into(),
        pads: vec![
            PadTarget {
                position: Point::new(Nm::new(0), Nm::new(500_000)),
                layer_mask: 1,
                pad_size: (Nm::new(100_000), Nm::new(100_000)),
                pin: "1".into(),
            },
            PadTarget {
                position: Point::new(Nm::new(2_900_000), Nm::new(500_000)),
                layer_mask: 1,
                pad_size: (Nm::new(100_000), Nm::new(100_000)),
                pin: "2".into(),
            },
        ],
    };
    let ratsnest = vec![net1];

    // Now create a wall that blocks vertical routing at x=15
    // (but net 1's horizontal route at y=5 is also blocking)
    // Net 2 needs to go from (15, 0) to (15, 9) — crosses net 1
    let mut routed_paths: HashMap<u32, Vec<Vec<GridNode>>> = HashMap::new();
    routed_paths.insert(1, vec![path1.unwrap()]);

    let result = attempt_ripup_reroute(
        &mut grid,
        (15, 0, 0),
        (15, 9, 0),
        false,
        2,
        &mut routed_paths,
        &ratsnest,
        &rules,
        &config,
    );

    // The rip-up should have succeeded: removed net 1, routed net 2,
    // then re-routed net 1 around net 2
    assert!(
        result.is_some(),
        "Rip-up/reroute should succeed for crossing nets"
    );

    // Net 1 should still be in routed_paths (re-routed)
    assert!(
        routed_paths.contains_key(&1),
        "Victim net 1 should be re-routed"
    );
}

